<?php declare(strict_types=1);
use Kulturhus\Native\Shared\Db;
use Kulturhus\Verein\{ExpenseReimbursements,Finance,MemberBankVault,Permissions,TransferOrders};

/** A genuine saved reimbursement account does not need a collection mandate or member-admin grant. */
function ownTransferNativeMemberBank(PDO $db,callable $check,array $f):void
{
    $person='own-transfer-reimbursement-person';$owner='own-transfer-reimbursement-owner';$name='Own reimbursed member '.str_repeat('Ö',80);$key=static fn():string=>bin2hex(random_bytes(16));
    Db::run($db,"INSERT INTO contacts(id,club_id,kind,name)VALUES(?,?,'person',?)",[$person,$f['club'],$name]);Db::run($db,"INSERT INTO memberships(id,club_id,contact_id,member_number,status,starts_on)VALUES(?,?,?,?,'aktiv','2020-01-01')",['own-transfer-reimbursement-membership',$f['club'],$person,'OWN-TRANSFER-MEMBER']);Db::run($db,"INSERT INTO actors(id,club_id,role,contact_id,is_superuser)VALUES(?,?,'member',?,0)",[$owner,$f['club'],$person]);
    $session=hash('sha256','Own actual reimbursement account owner step-up');$vault=new MemberBankVault($db,$owner,$f['path']);$bank=['holder'=>'Own actual separate holder '.str_repeat('Ä',110),'iban'=>'DE12500105170648489890','bic'=>'PBNKDEFFXXX'];
    $save=static function(int $version,array $data)use($db,$f,$person,$owner,$vault,$session):void{$token=bin2hex(random_bytes(32));Db::run($db,'INSERT INTO member_bank_grants VALUES(?,?,?,?,?,?,?,?,?,NULL)',[hash('sha256',$token),$f['club'],$owner,$person,'save',$version,MemberBankVault::payloadHash('save',$data),$session,time()+120]);$vault->save($person,$version,$data,$token,$session);};$save(0,$bank);
    $source=($f['entry'])('Own actual member advance invoice');$claims=new ExpenseReimbursements($db,$f['actor']);$claim=$claims->createForEntry($source['entry'],$person,'member',$key());$claims->approve($claim,1,$key());$finance=new Finance($db,$f['actor']);$transactions=$finance->transactions();$input=($f['inputFor'])($source['entry']);$before=ownOriginalDatabaseHash($db,$f['tables']);$review=$f['native']->prepare($input);
    $check($review['source']['preview']['source']['recipient']['name']===$bank['holder']&&$review['source']['preview']['source']['recipient_contact_name']===$name&&$review['source']['preview']['source']['recipient']['xml_name']===mb_substr($bank['holder'],0,70),'new actual reimbursement binds the whole real bank holder separately from the whole member name and the exact70-character bank name');
    $check(ownOriginalDatabaseHash($db,$f['tables'])===$before&&Permissions::actor($db,$f['actor'])['members_access']==='none'&&$vault->summary($person)['status']==='saved','actual saved reimbursement account preview writes no read audit and needs neither a mandate nor member administration');
    $first=$f['native']->accept($input,$key(),$review['hash'],true);$order=$first['result']['order']['id'];$f['service']->approve($order,1);$payload=$f['service']->fintsPayload($order,2);$doc=new DOMDocument();$doc->loadXML($payload['xml'],LIBXML_NONET);$xpath=new DOMXPath($doc);$actualName=$xpath->evaluate('string(//*[local-name()="Cdtr"]/*[local-name()="Nm"])');$check($first['result']['source']['source_version']===2&&$actualName===mb_substr($bank['holder'],0,70)&&$doc->schemaValidate(dirname(__DIR__,3).'/banking/schemas/pain.001.001.09_GBIC_5.xsd'),'new encrypted version2 reimbursement exports the exact real holder in an actual XSD-qualified bank file');
    $sealed=$f['service']->get($order)['sealed_snapshot'];$reader=\Kulturhus\Native\TestSupport::db();$reader->beginTransaction();$reader->query('SELECT COUNT(*) FROM member_bank_records')->fetchColumn();
    try{$changed=$bank;$changed['holder']=mb_substr($bank['holder'],0,-1).'Z';$save(1,$changed);$before=ownOriginalDatabaseHash($db,$f['tables']);$denied=false;try{(new TransferOrders($reader,$f['actor'],new MemberBankVault($reader,$f['actor'],$f['path'])))->fintsPayload($order,2);}catch(DomainException){$denied=true;}$check($denied&&$reader->inTransaction(),'a genuine independent holder change beyond the70 XML characters still blocks an older bank reader through its whole-source hash');}finally{if($reader->inTransaction())$reader->rollBack();}
    $check(ownOriginalDatabaseHash($db,$f['tables'])===$before&&$f['native']->receipt($first['key'])===$first&&$f['service']->get($order)['sealed_snapshot']===$sealed&&$finance->transactions()===$transactions&&hash_file('sha256',$f['path'])===$f['keyHash'],'whole-holder revalidation preserves every earlier row, personal original, encrypted bank original, money movement and key');
    $writer=\Kulturhus\Native\TestSupport::db();$writer->beginTransaction();try{Db::run($writer,'SELECT contact_id FROM member_bank_records WHERE club_id=? AND contact_id=? FOR UPDATE NOWAIT',[$f['club'],$person])->fetchColumn();$busy=false;try{$f['service']->preview($source['entry'],$f['account'],$input['data']['execution_date'],$input['data']['purpose']);}catch(DomainException $failure){$busy=$failure->getCode()===503&&$failure->getMessage()==='Bankdaten oder Zahlungsberechtigungen werden gerade bearbeitet. Erneut prüfen.';}$check($busy,'actual independent reimbursement-account lock returns503 with a bank-data retry message and never invents a mandate requirement');}finally{$writer->rollBack();}
}
